(function(){'use strict';let busy=false,failures=0,timer;window.MochiPayNativeLanguage.mount(document.body);async function check(){if(busy)return;clearTimeout(timer);busy=true;const b=document.getElementById('check');b.disabled=true;const controller=new AbortController(),deadline=setTimeout(()=>controller.abort(),40000);let retry=false;try{const u=new URL('/status',location.origin),q=new URLSearchParams(location.search);u.searchParams.set('r',q.get('r')||'');u.searchParams.set('t',q.get('t')||'');const r=await fetch(u,{cache:'no-store',signal:controller.signal}),d=await r.json().catch(error=>{error.fatal=r.ok||r.status>=400&&r.status<500&&r.status!==408&&r.status!==429;throw error});if(!r.ok||!d.success){const error=new Error('Unable to verify payment details');error.fatal=d.retryable===false||(!d.retryable&&r.status>=400&&r.status<500&&r.status!==408&&r.status!==429);throw error}failures=0;document.getElementById('status').textContent=d.data.status==='PAID'?'Payment verified by the server.':'Current verified status: '+d.data.status}catch(error){failures++;retry=!error.fatal;document.getElementById('status').textContent=error.fatal?'Do not send another payment. Contact the store to review this order.':failures>=3?'Connection failed. Your order is saved. Please check again.':'Loading payment details…'}finally{clearTimeout(deadline);busy=false;b.disabled=false;if(retry)timer=setTimeout(check,Math.min(60000,failures*15000))}}document.getElementById('check').onclick=check;check()})();
